// Some portions generated by Claude
package org.eclipse.rdf4j.query.parser.sparql;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.Assertions.assertAll;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.model.vocabulary.WINF;
import org.eclipse.rdf4j.query.MalformedQueryException;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.ProjectionElem;
import org.eclipse.rdf4j.query.algebra.QueryModelNode;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Window;
import org.eclipse.rdf4j.query.algebra.WindowFunctionCall;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.eclipse.rdf4j.query.parser.ParsedTupleQuery;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.function.Executable;

/**
 * Placement edge cases for {@code winf:} window functions: every position other than an aliased SELECT expression is a
 * syntax error with a message that names the offending call, specification markers are only valid inside a window call,
 * and the parser copes with very large queries.
 */
class WindowFunctionPlacementEdgeCaseTest {

	private static final String PREFIX = "PREFIX winf: <http://rdf4j.org/function/window#> PREFIX ex: <http://ex/> ";

	private static final String SELECT_ONLY = "may only be used in a SELECT expression";

	private static TupleExpr parse(String query) {
		TupleExpr expr = ((ParsedTupleQuery) new SPARQLParser().parseQuery(PREFIX + query, null)).getTupleExpr();
		return expr instanceof QueryRoot root ? root.getArg() : expr;
	}

	/** All Window operators, found with an explicit stack so that a 20 000-deep Join chain cannot overflow. */
	private static List<Window> windows(TupleExpr expr) {
		List<Window> windows = new ArrayList<>();
		List<QueryModelNode> children = new ArrayList<>();
		AbstractQueryModelVisitor<RuntimeException> childCollector = new AbstractQueryModelVisitor<>() {
			@Override
			protected void meetNode(QueryModelNode child) {
				children.add(child);
			}
		};
		Deque<QueryModelNode> pending = new ArrayDeque<>();
		pending.push(expr);
		while (!pending.isEmpty()) {
			QueryModelNode node = pending.pop();
			if (node instanceof Window window) {
				windows.add(window);
			}
			children.clear();
			node.visitChildren(childCollector);
			for (int i = children.size() - 1; i >= 0; i--) {
				pending.push(children.get(i));
			}
		}
		return windows;
	}

	private static void assertRejected(Map<String, String> queryToMessage) {
		List<Executable> cases = new ArrayList<>();
		queryToMessage.forEach((query, message) -> cases.add(() -> assertThatThrownBy(() -> parse(query)).as(query)
				.isInstanceOf(MalformedQueryException.class)
				.hasMessageContaining(message)));
		assertAll(cases);
	}

	@Test
	void windowCallInForbiddenPositionsIsRejectedWithClearMessage() {
		Map<String, String> cases = new LinkedHashMap<>();
		// BIND
		cases.put("SELECT ?a WHERE { ?x ex:s ?s BIND(winf:rowNumber() AS ?a) }", SELECT_ONLY);
		// FILTER
		cases.put("SELECT ?x WHERE { ?x ex:s ?s FILTER(winf:rank(winf:orderBy(?s)) = 1) }", SELECT_ONLY);
		// HAVING
		cases.put("SELECT ?x (COUNT(?s) AS ?c) WHERE { ?x ex:s ?s } GROUP BY ?x HAVING (winf:rowNumber() > 1)",
				SELECT_ONLY);
		// GROUP BY
		cases.put("SELECT ?k WHERE { ?x ex:s ?s } GROUP BY (winf:rowNumber() AS ?k)", SELECT_ONLY);
		// ORDER BY
		cases.put("SELECT ?x WHERE { ?x ex:s ?s } ORDER BY winf:rank(winf:orderBy(?s))", SELECT_ONLY);
		cases.put("SELECT ?x WHERE { ?x ex:s ?s } ORDER BY DESC(winf:rowNumber())", SELECT_ONLY);
		// EXISTS / NOT EXISTS
		cases.put("SELECT ?x WHERE { ?x ex:s ?s FILTER EXISTS { ?x ex:t ?t FILTER(winf:rowNumber() > 0) } }",
				SELECT_ONLY);
		cases.put("SELECT ?x WHERE { ?x ex:s ?s FILTER NOT EXISTS { ?x ex:t ?t BIND(winf:rowNumber() AS ?n) } }",
				SELECT_ONLY);
		// inside another window function
		cases.put("SELECT (winf:sum(winf:rank(winf:orderBy(?s)), winf:orderBy(?s)) AS ?a) WHERE { ?x ex:s ?s }",
				"cannot be nested inside");
		// inside winf:partitionBy / winf:orderBy
		cases.put("SELECT (winf:sum(?s, winf:partitionBy(winf:rowNumber())) AS ?a) WHERE { ?x ex:s ?s }",
				"cannot be nested inside winf:partitionBy");
		cases.put("SELECT (winf:sum(?s, winf:orderBy(winf:desc(winf:rowNumber()))) AS ?a) WHERE { ?x ex:s ?s }",
				"cannot be nested inside winf:orderBy");
		// inside an aggregate
		cases.put("SELECT (SUM(winf:rowNumber()) AS ?a) WHERE { ?x ex:s ?s }", "cannot be used inside an aggregate");
		cases.put("SELECT (COUNT(DISTINCT winf:rank(winf:orderBy(?s))) AS ?a) WHERE { ?x ex:s ?s }",
				"cannot be used inside an aggregate");
		assertRejected(cases);
		// VALUES: a function call is not a data block value, so the grammar itself rejects it
		assertThatThrownBy(() -> parse("SELECT ?x WHERE { VALUES ?x { winf:rowNumber() } }"))
				.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> parse("SELECT ?x WHERE { ?x ex:s ?s } VALUES ?x { winf:rowNumber() }"))
				.isInstanceOf(MalformedQueryException.class);
	}

	@Test
	void specificationMarkersOutsideWindowCallAreRejected() {
		Map<String, String> cases = new LinkedHashMap<>();
		for (String marker : List.of("asc", "desc", "partitionBy", "orderBy")) {
			String expected = "winf:" + marker + " may only be used inside a window function call";
			cases.put("SELECT ?a WHERE { ?x ex:s ?s BIND(winf:" + marker + "(?s) AS ?a) }", expected);
			cases.put("SELECT ?x WHERE { ?x ex:s ?s FILTER(winf:" + marker + "(?s)) }", expected);
			cases.put("SELECT (winf:" + marker + "(?s) AS ?a) WHERE { ?x ex:s ?s }", expected);
			cases.put("SELECT (STR(winf:" + marker + "(?s)) AS ?a) WHERE { ?x ex:s ?s }", expected);
			cases.put("SELECT ?x WHERE { ?x ex:s ?s } ORDER BY winf:" + marker + "(?s)", expected);
		}
		for (String marker : List.of("rows", "range")) {
			String expected = "winf:" + marker + " may only be used inside a window function call";
			cases.put("SELECT ?a WHERE { ?x ex:s ?s BIND(winf:" + marker + "(-1, 0) AS ?a) }", expected);
			cases.put("SELECT (winf:" + marker + "(-1, 0) AS ?a) WHERE { ?x ex:s ?s }", expected);
			cases.put("SELECT (winf:" + marker + "(\"unbounded\", \"current\") + 1 AS ?a) WHERE { ?x ex:s ?s }",
					expected);
		}
		// direction markers are only valid as keys of winf:orderBy, not as direct window arguments
		cases.put("SELECT (winf:rank(winf:asc(?s)) AS ?a) WHERE { ?x ex:s ?s }",
				"winf:asc may only be used inside winf:orderBy");
		cases.put("SELECT (winf:sum(?s, winf:desc(?s)) AS ?a) WHERE { ?x ex:s ?s }",
				"winf:desc may only be used inside winf:orderBy");
		cases.put("SELECT (winf:rank(winf:orderBy(winf:desc(winf:asc(?s)))) AS ?a) WHERE { ?x ex:s ?s }",
				"cannot be nested inside winf:orderBy");
		assertRejected(cases);
	}

	@Test
	void frameWithoutOrderByIsAllowed() {
		// pins current behaviour: a frame does not require winf:orderBy (SQL permits ROWS frames without ORDER BY as
		// well); the frame is then applied over the partition in input order
		for (String frame : List.of("winf:rows(-1, 0)", "winf:rows(\"unbounded\", \"current\")",
				"winf:range(\"unbounded\", \"current row\")")) {
			TupleExpr expr = parse(
					"SELECT (winf:sum(?s, winf:partitionBy(?d), " + frame + ") AS ?a) WHERE { ?x ex:d ?d ; ex:s ?s }");
			List<Window> windows = windows(expr);
			assertThat(windows).as(frame).hasSize(1);
			WindowFunctionCall call = windows.get(0).getElements().get(0).getOperator();
			assertThat(call.hasExplicitFrame()).as(frame).isTrue();
			assertThat(call.getOrderBy()).as(frame).isEmpty();
			assertThat(call.getPartitionBy()).as(frame).hasSize(1);
		}
		TupleExpr bare = parse("SELECT (winf:count(?s, winf:rows(0, 1)) AS ?a) WHERE { ?x ex:s ?s }");
		WindowFunctionCall call = windows(bare).get(0).getElements().get(0).getOperator();
		assertThat(call.getFrameMode()).isEqualTo(WindowFunctionCall.FrameMode.ROWS);
		assertThat(call.getFrameStart()).isEqualTo(0L);
		assertThat(call.getFrameEnd()).isEqualTo(1L);
		assertThat(call.getOrderBy()).isEmpty();
		assertThat(call.getPartitionBy()).isEmpty();
	}

	@Test
	void selectStarCannotCarryWindowCallButSubSelectAliasCanBeReferencedOutside() {
		// SELECT * admits no expressions, so a window call next to it is a plain syntax error
		assertThatThrownBy(() -> parse("SELECT * (winf:rowNumber() AS ?rn) WHERE { ?x ex:s ?s }"))
				.isInstanceOf(MalformedQueryException.class);
		assertThatThrownBy(() -> parse("SELECT (winf:rowNumber() AS ?rn) * WHERE { ?x ex:s ?s }"))
				.isInstanceOf(MalformedQueryException.class);
		// the alias of a window call in a sub-select is an ordinary variable for the enclosing query
		TupleExpr expr = parse("SELECT * WHERE { { SELECT ?x (winf:rowNumber(winf:orderBy(?s)) AS ?rn)"
				+ " WHERE { ?x ex:s ?s } } FILTER(?rn <= 2) } ORDER BY ?rn");
		List<Window> windows = windows(expr);
		assertThat(windows).hasSize(1);
		assertThat(windows.get(0).getElements()).hasSize(1);
		assertThat(windows.get(0).getElements().get(0).getOperator().getURI()).isEqualTo(WINF.rowNumber.stringValue());
		assertThat(expr).isInstanceOf(Projection.class);
		assertThat(((Projection) expr).getProjectionElemList()
				.getElements()
				.stream()
				.map(ProjectionElem::getName)).containsExactlyInAnyOrder("x", "rn");
		// the sub-select's own projection also exposes the alias
		TupleExpr named = parse("SELECT ?rn WHERE { { SELECT ?x (winf:rank(winf:orderBy(?s)) AS ?rn)"
				+ " WHERE { ?x ex:s ?s } } }");
		assertThat(windows(named)).hasSize(1);
		assertThat(named.getBindingNames()).containsExactly("rn");
	}

	@Test
	void veryLargeQueryWithWindowFunctionParsesWithoutStackOverflow() {
		StringBuilder triples = new StringBuilder();
		for (int i = 0; i < 20000; i++) {
			triples.append(" [] ex:p \"").append(i).append("\" .\n");
		}
		String pattern = triples.toString();
		// the window-specific whole-tree passes (stray-call rejection, alias and GROUP BY checks) must walk 20 000
		// nested Joins iteratively, just like the other parser passes
		TupleExpr expr = parse("SELECT (winf:rowNumber() AS ?rn) (winf:count(?x, winf:orderBy(?x)) AS ?c)"
				+ " WHERE { ?x ex:q ?y .\n" + pattern + "}");
		assertThat(windows(expr)).hasSize(1);
		assertThat(windows(expr).get(0).getElements()).hasSize(2);
		TupleExpr grouped = parse("SELECT ?x (COUNT(?y) AS ?n) (winf:rank(winf:orderBy(winf:desc(COUNT(?y)))) AS ?r)"
				+ " WHERE { ?x ex:q ?y .\n" + pattern + "} GROUP BY ?x ORDER BY ?r");
		assertThat(windows(grouped)).hasSize(1);
	}
}
